for (const item of $input.all()) {
  const formDate = $input.first().json.Date
  const time = {
    tirggerAt: $input.first().json.timestamp,
    submittedAt: formDate,
    date: new Date(),
  }

  time.date = new Date(time.tirggerAt || time.submittedAt)
  const dateTime = DateTime.fromJSDate(time.date)

  item.json = {
    createdAt: dateTime.toFormat('yyyy-MM-dd hh:mm:ss'),
    slug:  dateTime.toFormat('yyyy-MM-dd'),
    time
  }
}

return $input.all();
